 // The approved prefab may serialize a guard pose. That is not the mathematical skin bind.
 // Derive a temporary review rest pose solely from unchanged original inverse-bind matrices.
 public static void RestoreMathematicalSkinBind(GameObject actor,Animator animator,string evidencePath=null){
  var skin=actor.GetComponentInChildren<SkinnedMeshRenderer>();var rig=animator?animator.transform:actor.transform;var bones=skin.bones;var binds=skin.sharedMesh.bindposes;if(bones.Length!=binds.Length)throw new Exception("Original bind matrix count mismatch");var matrices=binds.Select(m=>skin.transform.localToWorldMatrix*m.inverse).ToArray();
  Func<Transform,int> depth=t=>{int n=0;for(var p=t.parent;p;p=p.parent)n++;return n;};foreach(int i in Enumerable.Range(0,bones.Length).OrderBy(i=>depth(bones[i]))){if(bones[i]==actor.transform||bones[i]==rig||!bones[i].IsChildOf(rig))throw new Exception("Bind calibration must not move actor/rig world roots");bones[i].SetPositionAndRotation(matrices[i].GetColumn(3),matrices[i].rotation);}
  double max=0;for(int i=0;i<bones.Length;i++)for(int e=0;e<16;e++)max=Math.Max(max,Math.Abs(bones[i].localToWorldMatrix[e]-matrices[i][e]));var oracle=new OriginalSkinWorldOracle(skin);oracle.Refresh();var originalVertices=skin.sharedMesh.vertices;double surface=0,squaredSurface=0,position=0,rotation=0;int witness=-1;for(int i=0;i<originalVertices.Length;i++){double error=Vector3.Distance(oracle.VertexWorld(i),skin.transform.TransformPoint(originalVertices[i]));squaredSurface+=error*error;if(error>surface){surface=error;witness=i;}}for(int i=0;i<bones.Length;i++){position=Math.Max(position,Vector3.Distance(bones[i].position,matrices[i].GetColumn(3)));rotation=Math.Max(rotation,Angle(bones[i].rotation,matrices[i].rotation));}string bindOutput=evidencePath??"../art/source/unique-dances-20261018/audit/generic-sailor/true-bind-reconstruction-v4.csv";Directory.CreateDirectory(Path.GetDirectoryName(bindOutput));if(!File.Exists(bindOutput))File.WriteAllText(bindOutput,"actor,meshAssetGUID,meshSubassetLocalID,vertices,renderedVertices,triangles,bones,matrixElementMax,worldJointPositionMaxM,worldRotationMaxDeg,originalVertexWorldMaxM,originalVertexWorldRmsM,vertexWitness,originalLocalScalesPreserved\n");AssetDatabase.TryGetGUIDAndLocalFileIdentifier(skin.sharedMesh,out string meshGuid,out long meshLocalId);File.AppendAllText(bindOutput,actor.name+","+meshGuid+","+meshLocalId+","+originalVertices.Length+","+oracle.RenderedVertexCount+","+(skin.sharedMesh.triangles.Length/3)+","+bones.Length+","+max+","+position+","+rotation+","+surface+","+Math.Sqrt(squaredSurface/originalVertices.Length)+","+witness+",true\n");if(surface>.00001||position>.00001||rotation>.003)throw new Exception("Temporary original bind reconstruction physical-space mismatch matrix="+max+" surface="+surface+" position="+position+" angle="+rotation);Debug.Log("AGENT_RESULT temporary original skin bind reconstructed, max matrix element error="+max+"; source matrices/weights/vertices untouched");
 }
 static void Build(bool preserveGirdle,bool preserveSole,bool mathematicalBind=false,int actorIndex=9,int actionId=74,bool validate=true){
  string folder="Assets/UniqueDancesReview/Fighter-"+actorIndex,sourcePath="Assets/UniqueDancesReview/GenericSources/action-"+actionId+".fbx";
  string candidatePath=folder+(mathematicalBind?"/Review.exact-generic-anatomic-v4.prefab":preserveSole?"/Review.exact-generic-anatomic-v3.prefab":preserveGirdle?"/Review.exact-generic-anatomic-v2.prefab":"/Review.exact-generic.prefab");
  if(validate)UniqueDanceGenericSourceAudit.RunFor(actorIndex,actionId);
  var original=AssetDatabase.LoadAssetAtPath<GameContent>("Assets/LighFight/Content/GameContent.asset").fighters[actorIndex];var actor=(GameObject)PrefabUtility.InstantiatePrefab(original);var source=AssetDatabase.LoadAssetAtPath<GameObject>(sourcePath);GameObject donorBind=null;
  try{
   var animator=actor.GetComponentInChildren<Animator>();var nodes=animator.GetComponentsInChildren<Transform>(true);var oldP=nodes.Select(t=>t.localPosition).ToArray();var oldQ=nodes.Select(t=>t.localRotation).ToArray();var oldS=nodes.Select(t=>t.localScale).ToArray();
   if(mathematicalBind){RestoreMathematicalSkinBind(actor,animator,actorIndex==9?null:"../art/source/unique-dances-20261018/audit/generic-roster/true-bind-reconstruction.csv");donorBind=(GameObject)PrefabUtility.InstantiatePrefab(source);RestoreMathematicalSkinBind(donorBind,donorBind.GetComponentInChildren<Animator>(),actorIndex==9?null:"../art/source/unique-dances-20261018/audit/generic-roster/true-bind-reconstruction.csv");}
   var root=Clone((donorBind?donorBind:source).transform,actor.transform);root.name="ExactDanceSource";
   var component=actor.AddComponent<ExactGenericDanceRetarget>();component.source=AssetDatabase.LoadAssetAtPath<NativeSupportPoseData>(folder+"/Dance.generic.source.pose.asset");component.sourceRoot=root;component.targetAnimator=animator;component.grounding=actor.GetComponent<CandidateFootGrounding>();component.sourceMapped=Names.Select(n=>root.GetComponentsInChildren<Transform>(true).Single(t=>t.name==n)).ToArray();component.targetMapped=Human.Select(h=>animator.GetBoneTransform(h)).ToArray();component.targetNodes=nodes;
   var sb=component.sourceMapped;var tb=component.targetMapped;var bindWorld=tb.Select(t=>t.rotation).ToArray();Quaternion inverse=Quaternion.Inverse(actor.transform.rotation);component.bodyAlignment=(inverse*Basis(tb[14],tb[18],tb[5],tb[0]))*Quaternion.Inverse(inverse*Basis(sb[14],sb[18],sb[5],sb[0]));if(mathematicalBind){
    // Virtual T orientations start from real donor bind, never its serialized dance frame.
    // Preserve donor girdle/joint centres; straighten only upper/lower arm directions.
    Vector3 right=Basis(sb[14],sb[18],sb[5],sb[0])*Vector3.right;
    foreach(int b in new[]{7,8,11,12}){Vector3 current=sb[Child[b]].position-sb[b].position;Vector3 desired=(b<10?-right:right);sb[b].rotation=Quaternion.FromToRotation(current,desired)*sb[b].rotation;}
   }
   component.sourceRestRotations=sb.Select(t=>inverse*t.rotation).ToArray();component.sourceHipRest=actor.transform.InverseTransformPoint(sb[0].position);
   // Derived canonical T-pose only: anatomical source segment directions determine
   // animated rotations. Bind matrices, source/target assets and Avatar are untouched.
   for(int b=0;b<tb.Length;b++){if(preserveGirdle&&(b==6||b==10)||preserveSole&&(b==16||b==17||b==20||b==21)){tb[b].rotation=bindWorld[b];continue;}int child=Child[b];if(child<0)continue;Vector3 desired=actor.transform.rotation*component.bodyAlignment*(inverse*(sb[child].position-sb[b].position));Vector3 current=tb[child].position-tb[b].position;if(desired.sqrMagnitude<1e-10||current.sqrMagnitude<1e-10)throw new Exception("Degenerate canonical segment");tb[b].rotation=Quaternion.FromToRotation(current,desired)*tb[b].rotation;}
   component.targetCanonicalRotations=tb.Select(t=>inverse*t.rotation).ToArray();component.targetLocalPositions=nodes.Select(t=>t.localPosition).ToArray();component.targetLocalRotations=nodes.Select(t=>t.localRotation).ToArray();component.targetLocalScales=nodes.Select(t=>t.localScale).ToArray();component.targetHipRest=actor.transform.InverseTransformPoint(tb[0].position);
   component.hipHeightScale=(tb[0].position.y-(tb[16].position.y+tb[20].position.y)*.5f)/(sb[0].position.y-(sb[16].position.y+sb[20].position.y)*.5f);if(component.hipHeightScale<=0)throw new Exception("Invalid canonical height scale");
   var overlay=actor.GetComponent<NativeSupportOverlay>();overlay.entries=overlay.entries.Where(e=>e.state!="Dance").ToArray();component.nativeCorrectionCap=overlay.nativeMaxCorrection;component.inactiveCorrectionCap=overlay.baseMaxCorrection;
