   for(int i=0;i<nodes.Length;i++){nodes[i].localPosition=oldP[i];nodes[i].localRotation=oldQ[i];nodes[i].localScale=oldS[i];}
   PrefabUtility.SaveAsPrefabAsset(actor,candidatePath);AssetDatabase.SaveAssets();
  }finally{if(donorBind)UnityEngine.Object.DestroyImmediate(donorBind);foreach(var b in actor.GetComponents<MonoBehaviour>())if(b is IActorCurveWarmup w)w.Dispose();UnityEngine.Object.DestroyImmediate(actor);}
  if(validate)ParityPath(candidatePath,actorIndex!=9?"fighter-"+actorIndex+"-v4":mathematicalBind?"anatomic-v4":preserveSole?"anatomic-v3":preserveGirdle?"anatomic-v2":"direct-runtime",sourcePath,actorIndex==9?null:"../art/source/unique-dances-20261018/audit/generic-roster");
