 static void ParityPath(string candidatePath,string evidence,string sourcePath=null,string outputRoot=null){
  sourcePath=sourcePath??Source;
  var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(candidatePath);var candidate=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var independent=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var raw=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(sourcePath));
  try{
   foreach(var a in new[]{candidate,independent,raw}){foreach(var b in a.GetComponentsInChildren<MonoBehaviour>(true))b.enabled=false;var animator=a.GetComponentInChildren<Animator>();if(animator)animator.enabled=false;}
   var actual=candidate.GetComponent<ExactGenericDanceRetarget>();var oracle=independent.GetComponent<ExactGenericDanceRetarget>();var sourceBones=Names.Select(n=>raw.GetComponentsInChildren<Transform>(true).Single(t=>t.name==n)).ToArray();var clip=AssetDatabase.LoadAllAssetsAtPath(sourcePath).OfType<AnimationClip>().Single(c=>!c.name.StartsWith("__preview"));
   double maxAngle=0;float maxPosition=0;int samples=Mathf.CeilToInt(clip.length*317);var rows=new List<string>{"seconds,maxLocalRotationDeltaDeg,maxWorldBonePositionDeltaM"};
   foreach(float yaw in new[]{0f,90f,-90f,170f}){Vector3 rootPosition=yaw==0?Vector3.zero:new Vector3(.83f,.17f,-.41f);float rootScale=yaw==-90?1.3f:yaw==90?.7f:1;foreach(var a in new[]{candidate,independent}){a.transform.position=rootPosition;a.transform.rotation=Quaternion.Euler(0,yaw,0);a.transform.localScale=Vector3.one*rootScale;}
   for(int k=0;k<=samples;k++){float seconds=clip.length*k/samples;actual.EvaluateForReview(seconds);clip.SampleAnimation(raw,seconds);for(int n=0;n<oracle.targetNodes.Length;n++){var t=oracle.targetNodes[n];t.localPosition=oracle.targetLocalPositions[n];t.localRotation=oracle.targetLocalRotations[n];t.localScale=oracle.targetLocalScales[n];}
    Vector3 hip=oracle.targetHipRest+oracle.bodyAlignment*(sourceBones[0].position-oracle.sourceHipRest)*oracle.hipHeightScale;hip.x=oracle.targetHipRest.x;hip.z=oracle.targetHipRest.z;oracle.targetMapped[0].position=independent.transform.TransformPoint(hip);
    for(int b=0;b<oracle.targetMapped.Length;b++)oracle.targetMapped[b].rotation=independent.transform.rotation*oracle.bodyAlignment*sourceBones[b].rotation*Quaternion.Inverse(oracle.sourceRestRotations[b])*Quaternion.Inverse(oracle.bodyAlignment)*oracle.targetCanonicalRotations[b];
    double angle=0;float position=0;for(int n=0;n<actual.targetNodes.Length;n++){angle=Math.Max(angle,Angle(actual.targetNodes[n].localRotation,oracle.targetNodes[n].localRotation));position=Mathf.Max(position,Vector3.Distance(actual.targetNodes[n].position,oracle.targetNodes[n].position));}maxAngle=Math.Max(maxAngle,angle);maxPosition=Mathf.Max(maxPosition,position);rows.Add(yaw+":"+seconds+","+angle+","+position);
    if(candidate.transform.position!=rootPosition||Quaternion.Angle(candidate.transform.rotation,Quaternion.Euler(0,yaw,0))>.001f||candidate.transform.localScale!=Vector3.one*rootScale)throw new Exception("Dance overwrote actor world transform");
   }}
   string output=outputRoot??"../art/source/unique-dances-20261018/audit/generic-sailor";Directory.CreateDirectory(output);File.WriteAllLines(output+"/"+evidence+"-independent-parity.csv",rows);File.WriteAllText(output+"/"+evidence+"-summary.txt","rootYawCases=0,90,-90,170 scales=1,.7,1.3,1 samples="+((samples+1)*4)+" maxLocalAngleDeg="+maxAngle+" maxWorldPositionM="+maxPosition+" sourceNodes="+actual.sourceRoot.GetComponentsInChildren<Transform>(true).Length+" sourceRenderers="+actual.sourceRoot.GetComponentsInChildren<Renderer>(true).Length);if(maxAngle>.06||maxPosition>.00001f)throw new Exception("Direct runtime vs independent Generic FK failed "+maxAngle+" "+maxPosition);Debug.Log("AGENT_RESULT exact Generic dance runtime independent FK parity passed; visual/player gate pending");
  }finally{foreach(var a in new[]{candidate,independent,raw}){foreach(var b in a.GetComponents<MonoBehaviour>())if(b is IActorCurveWarmup w)w.Dispose();UnityEngine.Object.DestroyImmediate(a);}}
 }
 static Transform Clone(Transform from,Transform parent){var t=new GameObject(from.name).transform;t.SetParent(parent,false);t.localPosition=from.localPosition;t.localRotation=from.localRotation;t.localScale=from.localScale;foreach(Transform child in from)if(!child.GetComponent<Renderer>())Clone(child,t);return t;}
 static Quaternion Basis(Transform l,Transform r,Transform h,Transform hip){Vector3 up=(h.position-hip.position).normalized,right=(r.position-l.position).normalized;return Quaternion.LookRotation(Vector3.Cross(right,up).normalized,up);}
 static double Angle(Quaternion a,Quaternion b){double d=(double)a.x*b.x+(double)a.y*b.y+(double)a.z*b.z+(double)a.w*b.w,aa=(double)a.x*a.x+(double)a.y*a.y+(double)a.z*a.z+(double)a.w*a.w,bb=(double)b.x*b.x+(double)b.y*b.y+(double)b.z*b.z+(double)b.w*b.w;return 2*Math.Acos(Math.Min(1,Math.Abs(d)/Math.Sqrt(aa*bb)))*180/Math.PI;}
